package com.mushafi.app;
import android.animation.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
/** One opaque in-window curtain from Activity creation through the first app frame. */
public final class LaunchScreen {
 public static final int BACKGROUND=0xfff5f3ed;public static final long DURATION=5000;
 private final FrameLayout parent,curtain;private final ImageView logo;private final TextView message,name;private String language;private final Button retry;private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable dismissed;private AnimatorSet pulse;
 private android.webkit.WebView presentation;private boolean presentationReady,dark,destroyed;private volatile boolean showing;private boolean resumed,ready,finishing;private long elapsed,started;
 public LaunchScreen(Context context,FrameLayout root,Runnable dismissed,Runnable reload){parent=root;dark=context.getSharedPreferences("launch-style",0).getBoolean("dark",false);this.dismissed=dismissed;curtain=new FrameLayout(context);if(Build.VERSION.SDK_INT>=29)curtain.setForceDarkAllowed(false);curtain.setBackgroundColor(background());curtain.setClickable(true);curtain.setFocusableInTouchMode(true);curtain.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);curtain.setContentDescription(UiLocale.text(parent.getContext(),"جارٍ فتح مصحفي"));curtain.setVisibility(View.GONE);
  logo=new ImageView(context);logo.setImageResource(R.drawable.launch_symbol);logo.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);FrameLayout.LayoutParams icon=new FrameLayout.LayoutParams(dp(context,132),dp(context,132),Gravity.CENTER);curtain.addView(logo,icon);
  LinearLayout text=new LinearLayout(context);text.setGravity(Gravity.CENTER);text.setOrientation(LinearLayout.VERTICAL);FrameLayout.LayoutParams copy=new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER);text.setTranslationY(dp(context,130));curtain.addView(text,copy);
  name=new TextView(context);name.setText(UiLocale.text(parent.getContext(),"جارٍ تجهيز مصحفك"));name.setTextSize(25);name.setTextColor(dark?NightPalette.INK:0xff213c31);name.setGravity(Gravity.CENTER);text.addView(name);
  message=new TextView(context);message.setText(UiLocale.text(parent.getContext(),"نهيّئ لك البداية"));message.setTextSize(14);message.setTextColor(dark?NightPalette.MUTED:0xff7e897e);message.setPadding(0,dp(context,12),0,0);message.setGravity(Gravity.CENTER);text.addView(message);
  retry=new Button(context);retry.setText(UiLocale.text(parent.getContext(),"إعادة المحاولة"));retry.setVisibility(View.GONE);retry.setTextColor(dark?NightPalette.GOLD:0xff213c31);retry.setBackgroundTintList(android.content.res.ColorStateList.valueOf(dark?NightPalette.SURFACE:0xfff5f3ed));retry.setOnClickListener(v->{show();reload.run();});text.addView(retry);curtain.addOnLayoutChangeListener((v,l,t,rr,b,ol,ot,or_,ob)->{text.setTranslationY(Math.min(dp(context,130),(b-t)*.32f));int size=Math.min(dp(context,132),Math.round((b-t)*.66f));android.view.ViewGroup.LayoutParams lp=logo.getLayoutParams();if(size>0&&lp.width!=size){lp.width=size;lp.height=size;logo.setLayoutParams(lp);}});presentation=new android.webkit.WebView(context);presentation.setBackgroundColor(background());presentation.setVisibility(View.INVISIBLE);presentation.addJavascriptInterface(new Object(){@android.webkit.JavascriptInterface public void ready(){handler.post(()->{if(destroyed)return;presentation.postVisualStateCallback(1,new android.webkit.WebView.VisualStateCallback(){@Override public void onComplete(long id){if(destroyed)return;presentationReady=true;presentation.setVisibility(View.VISIBLE);}});});}},"LaunchFrame");presentation.getSettings().setJavaScriptEnabled(true);presentation.getSettings().setAllowContentAccess(false);presentation.getSettings().setAllowFileAccess(false);presentation.getSettings().setAllowFileAccessFromFileURLs(false);presentation.getSettings().setAllowUniversalAccessFromFileURLs(false);presentation.getSettings().setMixedContentMode(android.webkit.WebSettings.MIXED_CONTENT_NEVER_ALLOW);presentation.setWebViewClient(new android.webkit.WebViewClient(){@Override public boolean shouldOverrideUrlLoading(android.webkit.WebView view,android.webkit.WebResourceRequest request){return true;}@Override public boolean shouldOverrideUrlLoading(android.webkit.WebView view,String url){return true;}@Override public void onPageFinished(android.webkit.WebView view,String url){presentation.evaluateJavascript("launchTheme("+dark+");document.fonts.ready.then(function(){requestAnimationFrame(function(){requestAnimationFrame(function(){LaunchFrame.ready()})})})",null);}});curtain.addView(presentation,new FrameLayout.LayoutParams(-1,-1));loadPresentation();root.addView(curtain,new FrameLayout.LayoutParams(-1,-1));
 }
 private int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 public static int initialBackground(Context context){return context.getSharedPreferences("launch-style",0).getBoolean("dark",false)?NightPalette.BACKGROUND:BACKGROUND;}
 public int background(){return dark?NightPalette.BACKGROUND:BACKGROUND;}
 public void setTheme(boolean value){dark=value;name.setTextColor(dark?NightPalette.INK:0xff213c31);message.setTextColor(dark?NightPalette.MUTED:0xff7e897e);retry.setTextColor(dark?NightPalette.GOLD:0xff213c31);retry.setBackgroundTintList(android.content.res.ColorStateList.valueOf(dark?NightPalette.SURFACE:0xfff5f3ed));parent.getContext().getSharedPreferences("launch-style",0).edit().putBoolean("dark",dark).apply();curtain.setBackgroundColor(background());presentation.setBackgroundColor(background());presentation.evaluateJavascript("typeof launchTheme===\"function\"&&launchTheme("+dark+")",null);}
 public boolean isShowing(){return showing;}
 private void loadPresentation(){language=UiLocale.language(parent.getContext());presentationReady=false;presentation.setVisibility(View.INVISIBLE);presentation.loadUrl("file:///android_asset/startup-loading.html?lang="+language+"&dark="+(dark?"1":"0"));}
 public void show(){if(!UiLocale.language(parent.getContext()).equals(language))loadPresentation();name.setText(UiLocale.text(parent.getContext(),"جارٍ تجهيز مصحفك"));retry.setText(UiLocale.text(parent.getContext(),"إعادة المحاولة"));curtain.setContentDescription(UiLocale.text(parent.getContext(),"جارٍ فتح مصحفي"));handler.removeCallbacksAndMessages(null);curtain.animate().cancel();finishing=false;showing=true;elapsed=0;started=SystemClock.elapsedRealtime();presentation.setVisibility(presentationReady?View.VISIBLE:View.INVISIBLE);curtain.setAlpha(1);curtain.setVisibility(View.VISIBLE);curtain.bringToFront();curtain.requestFocus();message.setText(UiLocale.text(parent.getContext(),"نهيّئ لك البداية"));retry.setVisibility(View.GONE);if(resumed){animateLogo();handler.post(tick);}}
 public void pageLoading(){ready=false;if(!showing)show();}
 public void pageReady(){ready=true;if(showing&&resumed)handler.post(tick);}
 public void resume(){if(resumed)return;presentation.onResume();resumed=true;started=SystemClock.elapsedRealtime();if(showing){animateLogo();handler.post(tick);}}
 public void pause(){if(!resumed)return;presentation.onPause();if(showing)elapsed+=SystemClock.elapsedRealtime()-started;resumed=false;handler.removeCallbacksAndMessages(null);if(finishing){curtain.animate().cancel();curtain.setAlpha(1);finishing=false;}stopPulse();}
 private final Runnable tick=new Runnable(){public void run(){if(!showing||!resumed||finishing)return;long time=elapsed+SystemClock.elapsedRealtime()-started;if(presentationReady)presentation.evaluateJavascript("launchProgress("+time+","+ready+")",null);if(time>=DURATION&&ready&&presentationReady){finishing=true;stopPulse();curtain.animate().alpha(0).setDuration(500).withEndAction(()->{if(!resumed)return;showing=false;finishing=false;curtain.setVisibility(View.GONE);dismissed.run();}).start();return;}if(time>=30000&&!ready){presentation.setVisibility(View.GONE);message.setText(UiLocale.text(parent.getContext(),"تعذر تجهيز الواجهة، أعد المحاولة"));retry.setVisibility(View.VISIBLE);}handler.postDelayed(this,80);}};
 private void animateLogo(){stopPulse();if(Build.VERSION.SDK_INT>=26&&!ValueAnimator.areAnimatorsEnabled())return;ObjectAnimator x=ObjectAnimator.ofFloat(logo,View.SCALE_X,.97f,1.03f),y=ObjectAnimator.ofFloat(logo,View.SCALE_Y,.97f,1.03f),a=ObjectAnimator.ofFloat(logo,View.ALPHA,.78f,1f);for(ObjectAnimator anim:new ObjectAnimator[]{x,y,a}){anim.setDuration(1800);anim.setRepeatCount(ValueAnimator.INFINITE);anim.setRepeatMode(ValueAnimator.REVERSE);}pulse=new AnimatorSet();pulse.playTogether(x,y,a);pulse.start();}
 private void stopPulse(){if(pulse!=null){pulse.cancel();pulse=null;}logo.setAlpha(1);logo.setScaleX(1);logo.setScaleY(1);}
 public void destroy(){destroyed=true;resumed=false;handler.removeCallbacksAndMessages(null);curtain.animate().cancel();stopPulse();presentation.destroy();parent.removeView(curtain);showing=false;}
}
